package com.nyayaconnect.ai;
import com.nyayaconnect.auth.SpringAccess;import com.nyayaconnect.casemgmt.CaseAccessService;import com.nyayaconnect.common.Api;import com.nyayaconnect.document.DocumentDao;import com.nyayaconnect.document.DocumentIntegrityService;import com.nyayaconnect.security.AuthenticationFilter;import com.nyayaconnect.security.SessionUser;import jakarta.servlet.http.*;import org.apache.pdfbox.Loader;import org.apache.pdfbox.text.PDFTextStripper;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;
public final class DocumentIntelligenceServlet extends HttpServlet {private CaseAccessService access;private DocumentDao dao;private DocumentIntegrityService integrity;public void init(){access=SpringAccess.bean(getServletContext(),CaseAccessService.class);dao=SpringAccess.bean(getServletContext(),DocumentDao.class);integrity=SpringAccess.bean(getServletContext(),DocumentIntegrityService.class);}
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{try{SessionUser u=(SessionUser)req.getSession(false).getAttribute(AuthenticationFilter.SESSION_KEY);String[] p=req.getPathInfo().split("/");if(p.length<2)throw new IllegalArgumentException("Document id is required.");UUID id=UUID.fromString(p[1]);DocumentDao.DocumentRecord d=dao.find(id).orElseThrow(()->new FileNotFoundException("Document not found."));access.requireAccess(u,d.caseId());Path file=integrity.safePath(d.storageKey());String text=extract(file,d.mimeType());String clipped=text.replaceAll("\\s+"," ").trim();if(clipped.length()>8000)clipped=clipped.substring(0,8000);List<String> clauses=Arrays.stream(clipped.split("(?<=[.!?])\\s+" )).filter(x->x.length()>30).limit(8).toList();Api.json(res,200,Map.of("documentId",id,"documentName",d.originalName(),"docClassification",classify(d.originalName(),d.mimeType()),"plainLanguageSummary",clipped.isBlank()?"No machine-readable text was extracted. A lawyer should review the original document.":"Machine-extracted text is available for review. This is not a legal opinion.","extractedTextPreview",clipped,"keyClauses",clauses,"potentialRiskPoints",List.of("Verify extracted text against the original document.","Do not treat automated extraction as legal advice.","Scanned/image-only documents may require OCR."),"sourceVerified",false));}catch(SecurityException e){Api.error(res,403,"FORBIDDEN",e.getMessage());}catch(FileNotFoundException e){Api.error(res,404,"DOCUMENT_NOT_FOUND",e.getMessage());}catch(IllegalArgumentException e){Api.error(res,400,"INVALID_REQUEST",e.getMessage());}catch(Exception e){Api.error(res,500,"DOCUMENT_ANALYSIS_FAILED","Document analysis failed safely.");}}
 private static String extract(Path f,String mime)throws IOException{if("text/plain".equals(mime))return Files.readString(f,StandardCharsets.UTF_8);if("application/pdf".equals(mime)){try(var doc=Loader.loadPDF(f.toFile())){return new PDFTextStripper().getText(doc);}}return "";}
 private static String classify(String name,String mime){String n=name.toLowerCase(Locale.ROOT);if(n.contains("agreement")||n.contains("lease"))return "Agreement / Lease";if(n.contains("notice"))return "Legal Notice";if(n.contains("cheque")||n.contains("check"))return "Financial / Cheque Record";return mime.equals("application/pdf")?"PDF legal document":"Uploaded evidence";}
}
